// Regression Overlay — Distribution, route: jsx
// Source: original:gaps/regression-overlay
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from regression ----
// Shared by regression-overlay and residuals: the residual plot is the same
// dataset seen after the fit. Mulberry32 PRNG for determinism.
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rng = mulberry32(20260821);

function randomNormal(mean: number, stdDev: number) {
  const u1 = rng();
  const u2 = rng();
  const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  return mean + z * stdDev;
}

// Ad spend ($k) vs incremental sales: returns rise, then flatten and dip past
// saturation. Mildly nonlinear on purpose, so OLS and LOESS visibly disagree
// in the right tail — that disagreement is regression-overlay's argument.
const campaignScatter: { x: number; y: number }[] = Array.from({ length: 90 }, () => {
  const x = Math.round(rng() * 120) / 10;
  const y = Math.round((5 + 3 * x - 0.22 * x * x + randomNormal(0, 1.8)) * 10) / 10;
  return { x, y };
}).sort((a, b) => a.x - b.x);

/** Least-squares line through the points. */
function olsFit(points: { x: number; y: number }[]) {
  const n = points.length;
  const mx = points.reduce((s, p) => s + p.x, 0) / n;
  const my = points.reduce((s, p) => s + p.y, 0) / n;
  let sxx = 0;
  let sxy = 0;
  for (const p of points) {
    sxx += (p.x - mx) * (p.x - mx);
    sxy += (p.x - mx) * (p.y - my);
  }
  const slope = sxx === 0 ? 0 : sxy / sxx;
  return { slope, intercept: my - slope * mx };
}

/**
 * LOESS: tricube-weighted local linear regression, evaluated at each point's x.
 * Written fresh — nothing in d3 v7 provides it. `span` is the fraction of
 * points inside each local window.
 */
function loess(points: { x: number; y: number }[], span = 0.4) {
  const pts = [...points].sort((a, b) => a.x - b.x);
  const k = Math.max(2, Math.ceil(span * pts.length));
  return pts.map((p) => {
    const dists = pts.map((q) => Math.abs(q.x - p.x)).sort((a, b) => a - b);
    const h = dists[k - 1] || 1e-9;
    let sw = 0;
    let swx = 0;
    let swy = 0;
    let swxx = 0;
    let swxy = 0;
    for (const q of pts) {
      const d = Math.abs(q.x - p.x) / h;
      if (d >= 1) continue;
      const w = (1 - d * d * d) ** 3;
      sw += w;
      swx += w * q.x;
      swy += w * q.y;
      swxx += w * q.x * q.x;
      swxy += w * q.x * q.y;
    }
    const denom = sw * swxx - swx * swx;
    const slope = denom === 0 ? 0 : (sw * swxy - swx * swy) / denom;
    const intercept = (swy - slope * swx) / sw;
    return { x: p.x, y: intercept + slope * p.x };
  });
}

const MARGIN = { top: 16, right: 56, bottom: 36, left: 46 };

/** One observation per row; both fits are computed from these points. */
export type Data = { x: number; y: number }[];

export default function RegressionOverlay({ data = campaignScatter, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.62);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const fit = useMemo(() => olsFit(data), [data]);
  const smooth = useMemo(() => loess(data), [data]);

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data, (d) => d.x) as [number, number])
        .nice()
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data, (d) => d.y) as [number, number])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const loessPath = useMemo(
    () =>
      d3
        .line<{ x: number; y: number }>()
        .x((d) => x(d.x))
        .y((d) => y(d.y))
        .curve(d3.curveCatmullRom)(smooth) ?? '',
    [smooth, x, y]
  );

  const [x0, x1] = x.domain();

  const xTicks: Tick[] = useMemo(
    () => x.ticks(Math.max(3, Math.round(innerWidth / 70))).map((v) => ({ value: String(v), offset: x(v) })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Scatterplot with a least-squares line and a LOESS curve overlaid; the two fits diverge where the trend bends downward"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {data.map((d, i) => (
          <circle key={i} cx={x(d.x)} cy={y(d.y)} r={3} fill="var(--muted)" fillOpacity={0.5} />
        ))}
        <line
          x1={x(x0)}
          x2={x(x1)}
          y1={y(fit.intercept + fit.slope * x0)}
          y2={y(fit.intercept + fit.slope * x1)}
          stroke="var(--text)"
          strokeWidth={1.5}
          strokeDasharray="6 4"
        />
        <path d={loessPath} fill="none" stroke="var(--accent)" strokeWidth={2.5} />
        <text
          x={innerWidth + 6}
          y={y(fit.intercept + fit.slope * x1)}
          dy="0.32em"
          fontSize={11}
          fill="var(--text)"
        >
          OLS
        </text>
        <text
          x={innerWidth + 6}
          y={y(smooth[smooth.length - 1]?.y ?? 0)}
          dy="0.32em"
          fontSize={11}
          fill="var(--accent)"
        >
          LOESS
        </text>
      </g>
    </svg>
  );
}
